<script setup>import{Head,Link,useForm}from'@inertiajs/vue3';import AppLayout from'../../Layouts/AppLayout.vue';const p=defineProps({submission:Object,history:Array,canReview:Boolean,statuses:Array});const form=useForm({status:p.submission.status,reviewer_feedback:p.submission.reviewer_feedback||''});const size=n=>`${(n/1048576).toFixed(1)} MB`;</script><template><AppLayout><Head title="بررسی تکلیف"/><div class="space-y-5"><section class="rounded-2xl border bg-white p-5"><h1 class="text-xl font-bold">{{submission.assignment.title}}</h1><p>{{submission.student.first_name}} {{submission.student.last_name}} — تلاش {{submission.attempt_number}}</p><p v-if="submission.is_late" class="text-red-700">ارسال با تأخیر</p><p class="mt-4 whitespace-pre-line">{{submission.text_content}}</p><a v-for="f in submission.files" :href="`/submission-files/${f.id}`" class="mt-2 block text-teal-700">{{f.original_name}} — {{size(f.file_size)}}</a></section><section v-if="canReview" class="rounded-2xl border bg-white p-5"><h2 class="font-bold">بررسی</h2><form class="mt-3 space-y-3" @submit.prevent="form.patch(`/submissions/${submission.id}/review`)"><select v-model="form.status"><option v-for="s in statuses" :value="s.value">{{s.label}}</option></select><textarea v-model="form.reviewer_feedback" rows="4" class="w-full rounded-xl border p-3" placeholder="بازخورد"></textarea><button :disabled="form.processing" class="rounded-xl bg-teal-700 px-4 py-2 text-white">ثبت نتیجه</button><p class="text-red-600">{{form.errors.status}}</p></form></section></div></AppLayout></template>
